import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner input = new Scanner(System.in);
        int count = input.nextInt();
        if (count <= 11) {
            long[][] points = new long[count][5];
            for (int i = 0; i < count; i++) {
                for (int j = 0; j < 5; j++) {
                    points[i][j] = input.nextLong();
                }
            }
            long[][][] vectors = new long[count][count][5];
            for (int i = 0; i < count; i++) {
                for (int j = 0; j < count; j++) {
                    for (int k = 0; k < 5; k++) {
                        vectors[i][j][k] = points[j][k] - points[i][k];
                    }
                }
            }
            java.util.HashSet<Integer> excludedIndices = new java.util.HashSet<>();
            for (int i = 0; i < count; i++) {
                boolean isAffected = false;
                for (int j = 0; j < count; j++) {
                    for (int k = 0; k < count; k++) {
                        if (!equalVectors(vectors[i][j], vectors[i][k]) && isDotProductPositive(vectors[i][j], vectors[i][k])) {
                            excludedIndices.add(i + 1);
                            isAffected = true;
                            break;
                        }
                    }
                    if (isAffected) break;
                }
            }
            System.out.println(count - excludedIndices.size());
            for (int i = 1; i <= count; i++) {
                if (!excludedIndices.contains(i))
                    System.out.println(i);
            }
        } else {
            System.out.println(0);
        }
    }

    private static boolean equalVectors(long[] a, long[] b) {
        for (int i = 0; i < 5; i++) {
            if (a[i] != b[i]) return false;
        }
        return true;
    }

    private static boolean isDotProductPositive(long[] a, long[] b) {
        long total = 0;
        for (int i = 0; i < 5; i++) {
            total += a[i] * b[i];
        }
        return total > 0;
    }
}
